using System;using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;
public static class FixSecondComputerDesk {public static string Run(){if(EditorApplication.isPlaying||BuildPipeline.isBuildingPlayer)throw new Exception("Idle editor required");var target=GameObject.Find("Second computer desk").transform;if(target.childCount!=0)throw new Exception("Support desk already present");var source=GameObject.Find("Classroom - licensed source art").transform.Find("Desk/teacherDesk");var copy=UnityEngine.Object.Instantiate(source.gameObject,target,true);copy.name="Reused classroom teacher desk";copy.transform.position+=new Vector3(2.1f,0,-1.1f);var surface=UnityEngine.Object.FindAnyObjectByType<NavMeshSurface>();surface.BuildNavMesh();var generated=surface.navMeshData;var saved=AssetDatabase.LoadAssetAtPath<NavMeshData>("Assets/_FireSafety/SchoolExpansion/Navigation/SchoolNavMesh.asset");EditorUtility.CopySerialized(generated,saved);surface.RemoveData();surface.navMeshData=saved;surface.AddData();UnityEngine.Object.DestroyImmediate(generated);EditorUtility.SetDirty(saved);EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Added original matching desk geometry and colliders beneath computer 2; saved navigation mesh.";}}
